#!/usr/bin/env python3
"""Patch a CI-generated Flutter android build.gradle(.kts) with a release
signing config driven by KEYSTORE_* environment variables.

Usage: patch_android_signing.py <android/app directory>

The DreamTX repo does not commit the android platform folder; it is
regenerated by `flutter create` on every CI run. This script runs right after
it and injects:

  * a `signingConfigs.release` entry reading the keystore from
    app/android/app/release-keystore.jks and credentials from env vars
    (KEYSTORE_PASSWORD / KEY_ALIAS / KEY_PASSWORD);
  * a conditional `signingConfig` in buildTypes.release that falls back to
    debug signing when the env vars are absent (e.g. fork PRs), so those
    builds keep working.

Exits non-zero if the expected anchor lines cannot be found - we would
rather fail loudly than silently ship a debug-signed release APK.
"""
import os
import re
import sys


def main() -> int:
    if len(sys.argv) != 2:
        print("usage: patch_android_signing.py <android/app dir>", file=sys.stderr)
        return 2
    app_dir = sys.argv[1]

    gradle = None
    for name in ("build.gradle.kts", "build.gradle"):
        p = os.path.join(app_dir, name)
        if os.path.exists(p):
            gradle = p
            break
    if gradle is None:
        print("patch_android_signing: no build.gradle(.kts) found in " + app_dir,
              file=sys.stderr)
        return 1

    src = open(gradle).read()
    if "release-keystore.jks" in src:
        print(f"patch_android_signing: {os.path.basename(gradle)} already patched")
        return 0

    kotlin = gradle.endswith(".kts")

    if kotlin:
        cfg_block = (
            "    signingConfigs {\n"
            "        create(\"release\") {\n"
            "            if (System.getenv(\"KEYSTORE_PASSWORD\") != null) {\n"
            "                storeFile = file(\"release-keystore.jks\")\n"
            "                storePassword = System.getenv(\"KEYSTORE_PASSWORD\")\n"
            "                keyAlias = System.getenv(\"KEY_ALIAS\")\n"
            "                keyPassword = System.getenv(\"KEY_PASSWORD\")\n"
            "            }\n"
            "        }\n"
            "    }\n"
        )
        pattern = re.compile(r'signingConfig\s*=\s*signingConfigs\.getByName\("debug"\)')
        replacement = (
            'signingConfig = if (System.getenv("KEYSTORE_PASSWORD") != null) '
            'signingConfigs.getByName("release") '
            'else signingConfigs.getByName("debug")'
        )
    else:
        cfg_block = (
            "    signingConfigs {\n"
            "        release {\n"
            "            if (System.getenv(\"KEYSTORE_PASSWORD\") != null) {\n"
            "                storeFile file(\"release-keystore.jks\")\n"
            "                storePassword System.getenv(\"KEYSTORE_PASSWORD\")\n"
            "                keyAlias System.getenv(\"KEY_ALIAS\")\n"
            "                keyPassword System.getenv(\"KEY_PASSWORD\")\n"
            "            }\n"
            "        }\n"
            "    }\n"
        )
        pattern = re.compile(r"signingConfig\s*=?\s*signingConfigs\.debug")
        replacement = (
            'signingConfig = (System.getenv("KEYSTORE_PASSWORD") != null ? '
            "signingConfigs.release : signingConfigs.debug)"
        )

    if not pattern.search(src):
        print(f"patch_android_signing: signing anchor not found in {gradle}",
              file=sys.stderr)
        return 1
    if "buildTypes {" not in src:
        print(f"patch_android_signing: buildTypes block not found in {gradle}",
              file=sys.stderr)
        return 1

    # Replace the debug signingConfig assignment inside buildTypes.release.
    src = pattern.sub(replacement, src, count=1)

    # Insert the signingConfigs block just above the buildTypes block,
    # preserving the original indentation of the buildTypes line.
    src = re.sub(r"([ \t]*)buildTypes \{",
                 lambda m: cfg_block + m.group(0),
                 src, count=1)

    open(gradle, "w").write(src)
    print(f"patch_android_signing: patched {gradle} "
          f"({'kotlin' if kotlin else 'groovy'} dsl) with release signing")
    return 0


if __name__ == "__main__":
    sys.exit(main())
